function file_table_insert(&$error_message = '') {
	global $Translation;

	// mm: can member insert record?
	$arrPerm = getTablePermissions('file_table');
	if(!$arrPerm['insert']) {
		$error_message = $Translation['no insert permission'];
		return false;
	}

	// automatic data_str_key if passed as filterer
	if(Request::val('filterer_data_str_key')) {
		$_REQUEST['data_str_key'] = Request::val('filterer_data_str_key');
	}

	$data = [
		'name_title_of_the_dataset' => Request::val('name_title_of_the_dataset', ''),
		'category_of_the_dataset' => Request::val('category_of_the_dataset', 'Agriculture'),
		'description_of_the_dataset' => br2nl(Request::val('description_of_the_dataset', '')),
		'geographic_coverage' => br2nl(Request::val('geographic_coverage', '')),
		'format_of_the_dataset' => Request::val('format_of_the_dataset', 'Spatial (Shapefiles, GeoJSON, etc.)'),
		'upload_file' => Request::fileUpload('upload_file', [
			'maxSize' => 1073741824,
			'types' => 'csv|xls|shp|geojson|tif|png|gif|shp|shx|dbf|prj|sbn|sbx|xml|geojson|json|kml|kmz|gml|csv|xls|xlsx|xlsm|ods|tif|tiff|jpg|jpeg|png|bmp|gif|img|ecw|sid|jp2',
			'noRename' => false,
			'dir' => '',
			'success' => function($name, $selected_id) {
			},
			'failure' => function($selected_id, $fileRemoved) {
				if(!strlen(Request::val('SelectedID'))) return '';

				/* for empty upload fields, when saving a copy of an existing record, copy the original upload field */
				return existing_value('file_table', 'upload_file', Request::val('SelectedID'));
			},
		]),
		'created_by' => parseCode('<%%creatorUsername%%>', true),
		'created_at' => parseCode('<%%creationDateTime%%>', true),
	];


	// automatic data_str_key if passed as filterer
	if(Request::val('filterer_data_str_key')) {
		$data['data_str_key'] = Request::val('filterer_data_str_key');
	}
	// record owner is current user
	$recordOwner = getLoggedMemberID();

	$recID = tableInsert('file_table', $data, $recordOwner, $error_message);

	// if this record is a copy of another record, copy children if applicable
	if(strlen(Request::val('SelectedID')) && $recID !== false)
		file_table_copy_children($recID, Request::val('SelectedID'));

	return $recID;
}

function file_table_copy_children($destination_id, $source_id) {
	global $Translation;
	$requests = []; // array of curl handlers for launching insert requests
	$eo = ['silentErrors' => true];
	$safe_sid = makeSafe($source_id);
	$currentUsername = getLoggedMemberID();
	$errorMessage = '';

	// launch requests, asynchronously
	curl_batch($requests);
}

function file_table_delete($selected_id, $AllowDeleteOfParents = false, $skipChecks = false) {
	// insure referential integrity ...
	global $Translation;
	$selected_id = makeSafe($selected_id);

	// mm: can member delete record?
	if(!check_record_permission('file_table', $selected_id, 'delete')) {
		return $Translation['You don\'t have enough permissions to delete this record'];
	}

	// hook: file_table_before_delete
	if(function_exists('file_table_before_delete')) {
		$args = [];
		if(!file_table_before_delete($selected_id, $skipChecks, getMemberInfo(), $args))
			return $Translation['Couldn\'t delete this record'] . (
				!empty($args['error_message']) ?
					'<div class="text-bold">' . strip_tags($args['error_message']) . '</div>'
					: '' 
			);
	}

	sql("DELETE FROM `file_table` WHERE `file_id`='{$selected_id}'", $eo);

	// hook: file_table_after_delete
	if(function_exists('file_table_after_delete')) {
		$args = [];
		file_table_after_delete($selected_id, getMemberInfo(), $args);
	}

	// mm: delete ownership data
	sql("DELETE FROM `membership_userrecords` WHERE `tableName`='file_table' AND `pkValue`='{$selected_id}'", $eo);
}

function file_table_update(&$selected_id, &$error_message = '') {
	global $Translation;

	// mm: can member edit record?
	if(!check_record_permission('file_table', $selected_id, 'edit')) return false;

	// since file_table.data_str_key is hidden in DV, force its stored value rather than submitted value
	$_REQUEST['data_str_key'] = sqlValue("SELECT `data_str_key` FROM `file_table` WHERE `file_id`='" . makeSafe($selected_id) . "'");

	$data = [
		'name_title_of_the_dataset' => Request::val('name_title_of_the_dataset', ''),
		'category_of_the_dataset' => Request::val('category_of_the_dataset', ''),
		'description_of_the_dataset' => br2nl(Request::val('description_of_the_dataset', '')),
		'geographic_coverage' => br2nl(Request::val('geographic_coverage', '')),
		'format_of_the_dataset' => Request::val('format_of_the_dataset', ''),
		'upload_file' => Request::fileUpload('upload_file', [
			'maxSize' => 1073741824,
			'types' => 'csv|xls|shp|geojson|tif|png|gif|shp|shx|dbf|prj|sbn|sbx|xml|geojson|json|kml|kmz|gml|csv|xls|xlsx|xlsm|ods|tif|tiff|jpg|jpeg|png|bmp|gif|img|ecw|sid|jp2',
			'noRename' => false,
			'dir' => '',
			'id' => $selected_id,
			'success' => function($name, $selected_id) {
			},
			'removeOnRequest' => true,
			'remove' => function($selected_id) {
				// do nothing: preserve removed files on server.
			},
			'failure' => function($selected_id, $fileRemoved) {
				if($fileRemoved) return '';
				return existing_value('file_table', 'upload_file', $selected_id);
			},
		]),
		'last_updated_by' => parseCode('<%%editorUsername%%>', false),
		'last_updated_at' => parseCode('<%%editingDateTime%%>', false),
	];

	if($data['name_title_of_the_dataset'] === '') {
		echo StyleSheet() . "\n\n<div class=\"alert alert-danger\">{$Translation['error:']} 'Name/Title of the dataset': {$Translation['field not null']}<br><br>";
		echo '<a href="" onclick="history.go(-1); return false;">' . $Translation['< back'] . '</a></div>';
		exit;
	}
	// get existing values
	$old_data = getRecord('file_table', $selected_id);
	if(is_array($old_data)) {
		$old_data = array_map('makeSafe', $old_data);
		$old_data['selectedID'] = makeSafe($selected_id);
	}

	$data['selectedID'] = makeSafe($selected_id);

	// hook: file_table_before_update
	if(function_exists('file_table_before_update')) {
		$args = ['old_data' => $old_data];
		if(!file_table_before_update($data, getMemberInfo(), $args)) {
			if(isset($args['error_message'])) $error_message = $args['error_message'];
			return false;
		}
	}

	$set = $data; unset($set['selectedID']);
	foreach ($set as $field => $value) {
		$set[$field] = ($value !== '' && $value !== NULL) ? $value : NULL;
	}

	if(!update(
		'file_table', 
		backtick_keys_once($set), 
		['`file_id`' => $selected_id], 
		$error_message
	)) {
		echo $error_message;
		echo '<a href="file_table_view.php?SelectedID=' . urlencode($selected_id) . "\">{$Translation['< back']}</a>";
		exit;
	}


	update_calc_fields('file_table', $data['selectedID'], calculated_fields()['file_table']);

	// hook: file_table_after_update
	if(function_exists('file_table_after_update')) {
		if($row = getRecord('file_table', $data['selectedID'])) $data = array_map('makeSafe', $row);

		$data['selectedID'] = $data['file_id'];
		$args = ['old_data' => $old_data];
		if(!file_table_after_update($data, getMemberInfo(), $args)) return;
	}

	// mm: update record update timestamp
	set_record_owner('file_table', $selected_id);
}

