	if(!$fieldsAreEditable) {
		$jsReadOnly = '';
		$jsReadOnly .= "\tjQuery('#name_title_of_the_dataset').replaceWith('<div class=\"form-control-static\" id=\"name_title_of_the_dataset\">' + (jQuery('#name_title_of_the_dataset').val() || '') + '</div>');\n";
		$jsReadOnly .= "\tjQuery('#category_of_the_dataset').replaceWith('<div class=\"form-control-static\" id=\"category_of_the_dataset\">' + (jQuery('#category_of_the_dataset').val() || '') + '</div>'); jQuery('#category_of_the_dataset-multi-selection-help').hide();\n";
		$jsReadOnly .= "\tjQuery('#description_of_the_dataset').replaceWith('<div class=\"form-control-static\" id=\"description_of_the_dataset\">' + (jQuery('#description_of_the_dataset').val() || '') + '</div>');\n";
		$jsReadOnly .= "\tjQuery('#geographic_coverage').replaceWith('<div class=\"form-control-static\" id=\"geographic_coverage\">' + (jQuery('#geographic_coverage').val() || '') + '</div>');\n";
		$jsReadOnly .= "\tjQuery('#format_of_the_dataset').replaceWith('<div class=\"form-control-static\" id=\"format_of_the_dataset\">' + (jQuery('#format_of_the_dataset').val() || '') + '</div>'); jQuery('#format_of_the_dataset-multi-selection-help').hide();\n";
		$jsReadOnly .= "\tjQuery('#upload_file').replaceWith('<div class=\"form-control-static\" id=\"upload_file\">' + (jQuery('#upload_file').val() || '') + '</div>');\n";
		$jsReadOnly .= "\tjQuery('#upload_file, #upload_file-edit-link').hide();\n";
		$jsReadOnly .= "\tjQuery('.select2-container').hide();\n";

		$noUploads = true;
	} else {
		// temporarily disable form change handler till time and datetime pickers are enabled
		$jsEditable = "\tjQuery('form').eq(0).data('already_changed', true);";
		$jsEditable .= "\tjQuery('form').eq(0).data('already_changed', false);"; // re-enable form change handler
	}

	// process combos
	$templateCode = str_replace('<%%COMBO(data_str_key)%%>', $combo_data_str_key->HTML, $templateCode);
	$templateCode = str_replace('<%%COMBOTEXT(data_str_key)%%>', $combo_data_str_key->MatchText, $templateCode);
	$templateCode = str_replace('<%%URLCOMBOTEXT(data_str_key)%%>', urlencode($combo_data_str_key->MatchText), $templateCode);
	$templateCode = str_replace('<%%COMBO(category_of_the_dataset)%%>', $combo_category_of_the_dataset->HTML, $templateCode);
	$templateCode = str_replace('<%%COMBOTEXT(category_of_the_dataset)%%>', $combo_category_of_the_dataset->SelectedData, $templateCode);
	$templateCode = str_replace('<%%COMBO(format_of_the_dataset)%%>', $combo_format_of_the_dataset->HTML, $templateCode);
	$templateCode = str_replace('<%%COMBOTEXT(format_of_the_dataset)%%>', $combo_format_of_the_dataset->SelectedData, $templateCode);

	/* lookup fields array: 'lookup field name' => ['parent table name', 'lookup field caption'] */
	$lookup_fields = ['data_str_key' => ['operation_dronagiri_data_submission_app', 'Data str key'], ];
	foreach($lookup_fields as $luf => $ptfc) {
		$pt_perm = getTablePermissions($ptfc[0]);

		// process foreign key links
		if(($pt_perm['view'] && isDetailViewEnabled($ptfc[0])) || $pt_perm['edit']) {
			$templateCode = str_replace("<%%PLINK({$luf})%%>", '<button type="button" class="btn btn-default view_parent" id="' . $ptfc[0] . '_view_parent" title="' . html_attr($Translation['View'] . ' ' . $ptfc[1]) . '"><i class="glyphicon glyphicon-eye-open"></i></button>', $templateCode);
		}

		// if user has insert permission to parent table of a lookup field, put an add new button
		if($pt_perm['insert'] /* && !Request::val('Embedded')*/) {
			$templateCode = str_replace("<%%ADDNEW({$ptfc[0]})%%>", '<button type="button" class="btn btn-default add_new_parent" id="' . $ptfc[0] . '_add_new" title="' . html_attr($Translation['Add New'] . ' ' . $ptfc[1]) . '"><i class="glyphicon glyphicon-plus text-success"></i></button>', $templateCode);
		}
	}

	// process images
	$templateCode = str_replace('<%%UPLOADFILE(file_id)%%>', '', $templateCode);
	$templateCode = str_replace('<%%UPLOADFILE(data_str_key)%%>', '', $templateCode);
	$templateCode = str_replace('<%%UPLOADFILE(name_title_of_the_dataset)%%>', '', $templateCode);
	$templateCode = str_replace('<%%UPLOADFILE(category_of_the_dataset)%%>', '', $templateCode);
	$templateCode = str_replace('<%%UPLOADFILE(description_of_the_dataset)%%>', '', $templateCode);
	$templateCode = str_replace('<%%UPLOADFILE(geographic_coverage)%%>', '', $templateCode);
	$templateCode = str_replace('<%%UPLOADFILE(format_of_the_dataset)%%>', '', $templateCode);
	$templateCode = str_replace('<%%UPLOADFILE(upload_file)%%>', ($noUploads ? '' : "<div>{$Translation['upload image']}</div>" . '<input type="file" name="upload_file" id="upload_file" data-filetypes="csv|xls|shp|geojson|tif|png|gif|shp|shx|dbf|prj|sbn|sbx|xml|geojson|json|kml|kmz|gml|csv|xls|xlsx|xlsm|ods|tif|tiff|jpg|jpeg|png|bmp|gif|img|ecw|sid|jp2" data-maxsize="1073741824" style="max-width: calc(100% - 1.5rem);" accept=".csv,.xls,.shp,.geojson,.tif,.png,.gif,.shp,.shx,.dbf,.prj,.sbn,.sbx,.xml,.geojson,.json,.kml,.kmz,.gml,.csv,.xls,.xlsx,.xlsm,.ods,.tif,.tiff,.jpg,.jpeg,.png,.bmp,.gif,.img,.ecw,.sid,.jp2">' . '<i class="text-danger clear-upload hidden pull-right" style="margin-top: -.1em; font-size: large;">&times;</i>'), $templateCode);
	if($allowUpdate && $row['upload_file'] != '') {
		$templateCode = str_replace('<%%REMOVEFILE(upload_file)%%>', '<input type="checkbox" name="upload_file_remove" id="upload_file_remove" value="1"> <label for="upload_file_remove" style="color: red; font-weight: bold;">'.$Translation['remove image'].'</label>', $templateCode);
	} else {
		$templateCode = str_replace('<%%REMOVEFILE(upload_file)%%>', '', $templateCode);
	}
	$templateCode = str_replace('<%%UPLOADFILE(created_by)%%>', '', $templateCode);
	$templateCode = str_replace('<%%UPLOADFILE(created_at)%%>', '', $templateCode);
	$templateCode = str_replace('<%%UPLOADFILE(last_updated_by)%%>', '', $templateCode);
	$templateCode = str_replace('<%%UPLOADFILE(last_updated_at)%%>', '', $templateCode);

	// process values
	if($hasSelectedId) {
		$templateCode = str_replace('<%%VALUE(file_id)%%>', safe_html($urow['file_id']), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(file_id)%%>', urlencode($urow['file_id']), $templateCode);
		if( $dvprint) $templateCode = str_replace('<%%VALUE(data_str_key)%%>', safe_html($urow['data_str_key']), $templateCode);
		if(!$dvprint) $templateCode = str_replace('<%%VALUE(data_str_key)%%>', html_attr($row['data_str_key']), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(data_str_key)%%>', urlencode($urow['data_str_key']), $templateCode);
		if( $dvprint) $templateCode = str_replace('<%%VALUE(name_title_of_the_dataset)%%>', safe_html($urow['name_title_of_the_dataset']), $templateCode);
		if(!$dvprint) $templateCode = str_replace('<%%VALUE(name_title_of_the_dataset)%%>', html_attr($row['name_title_of_the_dataset']), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(name_title_of_the_dataset)%%>', urlencode($urow['name_title_of_the_dataset']), $templateCode);
		if( $dvprint) $templateCode = str_replace('<%%VALUE(category_of_the_dataset)%%>', safe_html($urow['category_of_the_dataset']), $templateCode);
		if(!$dvprint) $templateCode = str_replace('<%%VALUE(category_of_the_dataset)%%>', html_attr($row['category_of_the_dataset']), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(category_of_the_dataset)%%>', urlencode($urow['category_of_the_dataset']), $templateCode);
		$templateCode = str_replace('<%%VALUE(description_of_the_dataset)%%>', safe_html($urow['description_of_the_dataset'], $fieldsAreEditable), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(description_of_the_dataset)%%>', urlencode($urow['description_of_the_dataset']), $templateCode);
		$templateCode = str_replace('<%%VALUE(geographic_coverage)%%>', safe_html($urow['geographic_coverage'], $fieldsAreEditable), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(geographic_coverage)%%>', urlencode($urow['geographic_coverage']), $templateCode);
		if( $dvprint) $templateCode = str_replace('<%%VALUE(format_of_the_dataset)%%>', safe_html($urow['format_of_the_dataset']), $templateCode);
		if(!$dvprint) $templateCode = str_replace('<%%VALUE(format_of_the_dataset)%%>', html_attr($row['format_of_the_dataset']), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(format_of_the_dataset)%%>', urlencode($urow['format_of_the_dataset']), $templateCode);
		if( $dvprint) $templateCode = str_replace('<%%VALUE(upload_file)%%>', safe_html($urow['upload_file']), $templateCode);
		if(!$dvprint) $templateCode = str_replace('<%%VALUE(upload_file)%%>', html_attr($row['upload_file']), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(upload_file)%%>', urlencode($urow['upload_file']), $templateCode);
		$templateCode = str_replace('<%%VALUE(created_by)%%>', safe_html($urow['created_by']), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(created_by)%%>', urlencode($urow['created_by']), $templateCode);
		$templateCode = str_replace('<%%VALUE(created_at)%%>', safe_html($urow['created_at']), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(created_at)%%>', urlencode($urow['created_at']), $templateCode);
		$templateCode = str_replace('<%%VALUE(last_updated_by)%%>', safe_html($urow['last_updated_by']), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(last_updated_by)%%>', urlencode($urow['last_updated_by']), $templateCode);
		$templateCode = str_replace('<%%VALUE(last_updated_at)%%>', safe_html($urow['last_updated_at']), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(last_updated_at)%%>', urlencode($urow['last_updated_at']), $templateCode);
	} else {
		$templateCode = str_replace('<%%VALUE(file_id)%%>', '', $templateCode);
		$templateCode = str_replace('<%%URLVALUE(file_id)%%>', urlencode(''), $templateCode);
		$templateCode = str_replace('<%%VALUE(data_str_key)%%>', ( Request::val('FilterField')[1]=='2' && Request::val('FilterOperator')[1]=='<=>' ? $combo_data_str_key->SelectedData : ''), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(data_str_key)%%>', urlencode( Request::val('FilterField')[1]=='2' && Request::val('FilterOperator')[1]=='<=>' ? $combo_data_str_key->SelectedData : ''), $templateCode);
		$templateCode = str_replace('<%%VALUE(name_title_of_the_dataset)%%>', '', $templateCode);
		$templateCode = str_replace('<%%URLVALUE(name_title_of_the_dataset)%%>', urlencode(''), $templateCode);
		$templateCode = str_replace('<%%VALUE(category_of_the_dataset)%%>', 'Agriculture', $templateCode);
		$templateCode = str_replace('<%%URLVALUE(category_of_the_dataset)%%>', urlencode('Agriculture'), $templateCode);
		$templateCode = str_replace('<%%VALUE(description_of_the_dataset)%%>', '', $templateCode);
		$templateCode = str_replace('<%%URLVALUE(description_of_the_dataset)%%>', urlencode(''), $templateCode);
		$templateCode = str_replace('<%%VALUE(geographic_coverage)%%>', '', $templateCode);
		$templateCode = str_replace('<%%URLVALUE(geographic_coverage)%%>', urlencode(''), $templateCode);
		$templateCode = str_replace('<%%VALUE(format_of_the_dataset)%%>', 'Spatial (Shapefiles, GeoJSON, etc.)', $templateCode);
		$templateCode = str_replace('<%%URLVALUE(format_of_the_dataset)%%>', urlencode('Spatial (Shapefiles, GeoJSON, etc.)'), $templateCode);
		$templateCode = str_replace('<%%VALUE(upload_file)%%>', '', $templateCode);
		$templateCode = str_replace('<%%URLVALUE(upload_file)%%>', urlencode(''), $templateCode);
		$templateCode = str_replace('<%%VALUE(created_by)%%>', '<%%creatorUsername%%>', $templateCode);
		$templateCode = str_replace('<%%URLVALUE(created_by)%%>', urlencode('<%%creatorUsername%%>'), $templateCode);
		$templateCode = str_replace('<%%VALUE(created_at)%%>', '<%%creationDateTime%%>', $templateCode);
		$templateCode = str_replace('<%%URLVALUE(created_at)%%>', urlencode('<%%creationDateTime%%>'), $templateCode);
		$templateCode = str_replace('<%%VALUE(last_updated_by)%%>', '<%%editorUsername%%>', $templateCode);
		$templateCode = str_replace('<%%URLVALUE(last_updated_by)%%>', urlencode('<%%editorUsername%%>'), $templateCode);
		$templateCode = str_replace('<%%VALUE(last_updated_at)%%>', '<%%editingDateTime%%>', $templateCode);
		$templateCode = str_replace('<%%URLVALUE(last_updated_at)%%>', urlencode('<%%editingDateTime%%>'), $templateCode);
	}

	// process translations
	$templateCode = parseTemplate($templateCode);

	// clear scrap
	$templateCode = str_replace('<%%', '<!-- ', $templateCode);
	$templateCode = str_replace('%%>', ' -->', $templateCode);

	// hide links to inaccessible tables
	if(Request::val('dvprint_x') == '') {
		$templateCode .= "\n\n<script>\$j(function() {\n";
		$arrTables = getTableList();
		foreach($arrTables as $name => $caption) {
			$templateCode .= "\t\$j('#{$name}_link').removeClass('hidden');\n";
			$templateCode .= "\t\$j('#xs_{$name}_link').removeClass('hidden');\n";
		}

		$templateCode .= $jsReadOnly;
		$templateCode .= $jsEditable;

		if(!$hasSelectedId) {
			$templateCode.="\n\tif(document.getElementById('upload_fileEdit')) { document.getElementById('upload_fileEdit').style.display='inline'; }";
			$templateCode.="\n\tif(document.getElementById('upload_fileEditLink')) { document.getElementById('upload_fileEditLink').style.display='none'; }";
		}

		$templateCode.="\n});</script>\n";
	}

	// ajaxed auto-fill fields
	$templateCode .= '<script>';
	$templateCode .= '$j(function() {';


	$templateCode.="});";
	$templateCode.="</script>";
	$templateCode .= $lookups;

	// handle enforced parent values for read-only lookup fields
	$filterField = Request::val('FilterField');
	$filterOperator = Request::val('FilterOperator');
	$filterValue = Request::val('FilterValue');

	// don't include blank images in lightbox gallery
	$templateCode = preg_replace('/blank.gif" data-lightbox=".*?"/', 'blank.gif"', $templateCode);

	// don't display empty email links
	$templateCode=preg_replace('/<a .*?href="mailto:".*?<\/a>/', '', $templateCode);

	/* default field values */
	$rdata = $jdata = get_defaults('file_table');
	if($hasSelectedId) {
		$jdata = get_joined_record('file_table', $selectedId);
		if($jdata === false) $jdata = get_defaults('file_table');
		$rdata = $row;
	}
	$templateCode .= loadView('file_table-ajax-cache', ['rdata' => $rdata, 'jdata' => $jdata]);

	// hook: file_table_dv
	if(function_exists('file_table_dv')) {
		$args = [];
		file_table_dv(($hasSelectedId ? $selectedId : FALSE), getMemberInfo(), $templateCode, $args);
	}

	return $templateCode;
}